@Bean
public Job importEmployeeJob(JobBuilderFactory jobBuilderFactory,
                             Step importEmployeeStep) {
    return jobBuilderFactory.get("importEmployeeJob")
            .incrementer(new RunIdIncrementer())
            .start(importEmployeeStep)
            .build();
}

@Bean
public Step importEmployeeStep(StepBuilderFactory stepBuilderFactory,
                               FlatFileItemReader<Employee> reader,
                               ItemProcessor<Employee, Employee> processor,
                               JdbcBatchItemWriter<Employee> writer) {
    return stepBuilderFactory.get("importEmployeeStep")
            .<Employee, Employee>chunk(100)
            .reader(reader)
            .processor(processor)
            .writer(writer)
            .build();
}

@Bean
public Job xmlToJsonJob(JobBuilderFactory jobBuilderFactory, Step xmlToJsonStep) {
    return jobBuilderFactory.get("xmlToJsonJob")
            .incrementer(new RunIdIncrementer())
            .start(xmlToJsonStep)
            .build();
}

@Bean
public Step xmlToJsonStep(StepBuilderFactory stepBuilderFactory,
                          StaxEventItemReader<Employee> reader,
                          ItemProcessor<Employee, Employee> processor,
                          JsonFileItemWriter<Employee> writer) {
    return stepBuilderFactory.get("xmlToJsonStep")
            .<Employee, Employee>chunk(50)
            .reader(reader)
            .processor(processor)
            .writer(writer)
            .build();
}

@Bean
public Job cleanupJob(JobBuilderFactory jobBuilderFactory, Step cleanupStep) {
    return jobBuilderFactory.get("cleanupJob")
            .incrementer(new RunIdIncrementer())
            .start(cleanupStep)
            .build();
}

@Bean
public Step cleanupStep(StepBuilderFactory stepBuilderFactory) {
    return stepBuilderFactory.get("cleanupStep")
            .tasklet((contribution, chunkContext) -> {
                Files.walk(Paths.get("/tmp"))
                        .filter(Files::isRegularFile)
                        .forEach(file -> file.toFile().delete());
                return RepeatStatus.FINISHED;
            })
            .build();
}

